-- Fecha de inauguracion de cada estacion de subte.
-- Fuente: Wikipedia, "List of Buenos Aires Underground stations" (consultada el 25/10/2026).
-- Las estaciones de tren quedan sin fecha hasta tener una fuente confiable.

ALTER TABLE station ADD COLUMN opened_on DATE;

